#!/usr/bin/env bash
# Generated by flext-infra. Local make setup installs the Git hooks that run
# this validator and exports PREK, the provisioned prek runner.
set -euo pipefail
stage="${1:?Git hook stage is required}"
# A bare assignment carries the substitution's status, so errexit stops on a
# git failure; inside `cd "$(...)"` it would be lost and `cd ""` would succeed.
toplevel="$(git rev-parse --show-toplevel)"
cd "${toplevel}"
case "${stage}" in
  pre-commit|pre-merge-commit|pre-push) ;;
  *) printf 'Unsupported Git hook stage: %s\n' "${stage}" >&2; exit 2 ;;
esac
# The shared-worktree contract forbids a clean-tree prerequisite, and the
# runner never removes unstaged work: --all-files validates the working tree
# as it is (a superset of the candidate) instead of hiding changes from it.
unset SKIP PRE_COMMIT_ALLOW_NO_CONFIG
"${PREK:?PREK must name the prek runner that make setup installed}" run --all-files --hook-stage "${stage}"
